//! Option handling (seeds, secrets) and algorithm families that need more than
//! plain string vectors: sha3.phpt, murmurhash3*.phpt, xxhash_*.phpt, plus
//! digests produced by compiling the reference C sources of php-src
//! (`ext/hash/xxhash/xxhash.h`, `ext/hash/murmur/*.c`) with inputs generated by
//! a small deterministic LCG (see `pattern`).

use php_hash::{HashError, HashOptions, hash, hash_with_options, new_hasher, to_hex};

enum In {
    Lit(&'static [u8]),
    Rep(&'static [u8], usize),
}

impl In {
    fn data(&self) -> Vec<u8> {
        match self {
            In::Lit(b) => b.to_vec(),
            In::Rep(b, n) => b.repeat(*n),
        }
    }
}

