/// Deterministic pseudo-random bytes (the same generator produced the C reference digests).
fn pattern(seed: u32, n: usize) -> Vec<u8> {
    let mut x = seed;
    (0..n)
        .map(|_| {
            x = x.wrapping_mul(1_664_525).wrapping_add(1_013_904_223);
            (x >> 24) as u8
        })
        .collect()
}

fn hex(algo: &str, data: &[u8], options: &HashOptions) -> String {
    to_hex(&hash_with_options(algo, data, options).unwrap())
}

fn incremental(algo: &str, pieces: &[&[u8]], options: &HashOptions) -> String {
    let mut h = new_hasher(algo, options).unwrap();
    for p in pieces {
        h.update(p);
    }
    to_hex(&h.finalize())
}

#[test]
fn sha3_phpt() {
    for (bits, subject, expected) in SHA3 {
        let algo = format!("sha3-{bits}");
        let data = SHA3_SUBJECTS[*subject].data();
        assert_eq!(
            to_hex(&hash(&algo, &data).unwrap()),
            *expected,
            "{algo} #{subject}"
        );
    }
}

#[test]
fn murmur3_phpt() {
    let none = HashOptions::none();
    assert_eq!(hex("murmur3a", b"foo", &none), "f6a5c420");
    assert_eq!(
        hex("murmur3c", b"Two hashes meet in a bar", &none),
        "8036c2707453c6f37348142be7eaf75c"
    );
    assert_eq!(
        hex("murmur3c", b"hash me!", &none),
        "c7009299985a5627a9280372a9280372"
    );
    assert_eq!(
        hex("murmur3f", b"Two hashes meet in a bar", &none),
        "40256ed26fa6ece7785092ed33c8b659"
    );
    assert_eq!(
        hex("murmur3f", b"hash me!", &none),
        "c43668294e89db0ba5772846e5804467"
    );
    for (algo, expected) in [
        ("murmur3a", "6440964d"),
        ("murmur3c", "2bcadca212d62deb69712a721e593089"),
        ("murmur3f", "81514cc240f57a165c95eb63f9c0eedf"),
    ] {
        assert_eq!(incremental(algo, &[b"hello", b" there"], &none), expected);
        assert_eq!(hex(algo, b"hello there", &none), expected);
    }
}

#[test]
fn murmur3_seed_phpt() {
    let pieces: [&[u8]; 6] = [b"Two", b" hashes", b" meet", b" in", b" a", b" bar."];
    for (algo, seed, expected) in [
        ("murmur3f", 42, "95855f9be0db784a5c37e878c4a4dcee"),
        ("murmur3c", 106, "f64c9eb40287fa686575163893e283b2"),
        ("murmur3a", 2345, "7f7ec59b"),
    ] {
        let opts = HashOptions::with_seed(seed);
        assert_eq!(incremental(algo, &pieces, &opts), expected, "{algo}");
        assert_eq!(
            hex(algo, b"Two hashes meet in a bar.", &opts),
            expected,
            "{algo}"
        );
    }
}

#[test]
fn xxhash_seed_phpt() {
    let text = b"Lorem ipsum dolor sit amet, consectetur adipiscing elit.";
    let pieces: [&[u8]; 4] = [
        b"Lorem",
        b" ipsum dolor",
        b" sit amet,",
        b" consectetur adipiscing elit.",
    ];
    let opts = HashOptions::with_seed(42);
    for (algo, expected) in [
        ("xxh32", "3d0cc7e5"),
        ("xxh64", "9c9aa071b5d22a15"),
        ("xxh3", "366409913c16b70d"),
        ("xxh128", "f87856a7589354e92aeca886c71ed7fb"),
    ] {
        assert_eq!(incremental(algo, &pieces, &opts), expected, "{algo}");
        assert_eq!(hex(algo, text, &opts), expected, "{algo}");
    }
    // `options: []` is the same as no options (xxhash_options_without_seed.phpt).
    for algo in ["xxh32", "xxh64", "xxh3", "xxh128"] {
        assert_eq!(
            hex(algo, b"x", &HashOptions::none()),
            to_hex(&hash(algo, b"x").unwrap())
        );
    }
}

#[test]
fn xxhash_secret_phpt() {
    let text = b"Lorem ipsum dolor sit amet, consectetur adipiscing elit.";
    let secret = vec![b'a'; 256];
    for (algo, expected) in [
        ("xxh3", "8028aa834c03557a"),
        ("xxh128", "54279097795e7218093a05d4d781cbb9"),
    ] {
        let opts = HashOptions::with_secret(secret.clone());
        assert_eq!(hex(algo, text, &opts), expected, "{algo}");
        // Seed and secret together are rejected, as are too short secrets.
        let both = HashOptions {
            seed: Some(24),
            secret: Some(secret.clone()),
        };
        assert_eq!(
            hash_with_options(algo, text, &both),
            Err(HashError::SeedAndSecret {
                algo: php_hash::find(algo).unwrap().name
            })
        );
        let err =
            hash_with_options(algo, text, &HashOptions::with_secret(vec![b'a'; 17])).unwrap_err();
        assert_eq!(
            err.to_string(),
            format!("{algo}: Secret length must be >= 136 bytes, 17 bytes passed")
        );
    }
    // Secrets above 256 bytes are truncated to 256 (PHP warns about it).
    let long = HashOptions::with_secret(vec![b'a'; 300]);
    assert_eq!(hex("xxh3", text, &long), "8028aa834c03557a");
}

#[test]
fn options_are_ignored_by_other_algorithms() {
    let opts = HashOptions {
        seed: Some(5),
        secret: Some(vec![1; 200]),
    };
    for algo in ["md5", "sha256", "crc32b", "whirlpool"] {
        assert_eq!(
            hash_with_options(algo, b"abc", &opts).unwrap(),
            hash(algo, b"abc").unwrap()
        );
    }
}

