    for &(algo, seed, secret_len, len, expected) in ROWS {
        let data = pattern(0x1234 + len as u32, len);
        let opts = HashOptions {
            seed,
            secret: (secret_len > 0).then(|| pattern(0x5ec7e7 + secret_len as u32, secret_len)),
        };
        assert_eq!(
            hex(algo, &data, &opts),
            expected,
            "{algo} seed {seed:?} secret {secret_len} len {len}"
        );
        // Streaming in awkward pieces must agree.
        let cut = len / 3;
        let (a, b) = data.split_at(cut);
        let (b1, b2) = b.split_at(b.len() / 2);
        assert_eq!(
            incremental(algo, &[a, b1, b2], &opts),
            expected,
            "{algo} streamed len {len}"
        );
        let bytes: Vec<&[u8]> = data.chunks(7).collect();
        assert_eq!(
            incremental(algo, &bytes, &opts),
            expected,
            "{algo} 7-byte chunks len {len}"
        );
    }
